CREATE VIEW lignes_ventes AS
  SELECT v.id, v.jour, p.nom, v.quantite * p.prix AS montant
  FROM ventes AS v JOIN produits AS p ON p.id = v.produit_id;
SELECT id, nom, montant FROM lignes_ventes WHERE montant > 2000 ORDER BY id;

CREATE VIEW tableau_produits AS
  SELECT p.nom, p.categorie, p.stock, coalesce(SUM(v.quantite * p.prix), 0) AS ca
  FROM produits AS p LEFT JOIN ventes AS v ON v.produit_id = p.id
  GROUP BY p.id;
SELECT nom, stock, ca FROM tableau_produits WHERE stock < 20 ORDER BY ca DESC, nom;
